"""Generates hardened QNX SDP 8.0 mkifs + QEMU x86_64/aarch64le verification scripts."""
from pathlib import Path

QEMU_X86_64_SH = """#!/usr/bin/env bash
# Generated by QNXGuard — QNX SDP 8.0 x86_64 mkifs + QEMU headless boot & smoke-test harness
set -euo pipefail

: "${QNX_HOST:?Source qnxsdp-env.sh first so QNX_HOST and QNX_TARGET are set}"
: "${QNX_TARGET:?Source qnxsdp-env.sh first so QNX_HOST and QNX_TARGET are set}"

BUILDFILE="${1:-qnx8_hardened.build}"
IFS_OUT="${2:-qnx8_x86_64.ifs}"

echo "[1/3] Running QNXGuard static gate on ${BUILDFILE}..."
python3 -m qnxguard scan "$(dirname "${BUILDFILE}")" --fail-on HIGH

echo "[2/3] Building QNX 8.0 IFS image via mkifs..."
mkifs -v "${BUILDFILE}" "${IFS_OUT}"

echo "[3/3] Booting ${IFS_OUT} under QEMU x86_64 (serial console)..."
qemu-system-x86_64 \\
  -m 1024M \\
  -smp 2 \\
  -nographic \\
  -serial mon:stdio \\
  -kernel "${IFS_OUT}" \\
  -netdev user,id=net0 \\
  -device virtio-net-pci,netdev=net0
"""

QEMU_AARCH64_SH = """#!/usr/bin/env bash
# Generated by QNXGuard — QNX SDP 8.0 aarch64le mkifs + QEMU virt machine harness
set -euo pipefail

: "${QNX_HOST:?Source qnxsdp-env.sh first}"
: "${QNX_TARGET:?Source qnxsdp-env.sh first}"

BUILDFILE="${1:-qnx8_aarch64.build}"
IFS_OUT="${2:-qnx8_aarch64.ifs}"

python3 -m qnxguard scan "$(dirname "${BUILDFILE}")" --fail-on HIGH
mkifs -v "${BUILDFILE}" "${IFS_OUT}"

qemu-system-aarch64 \\
  -machine virt,gic-version=3 \\
  -cpu cortex-a57 \\
  -m 1024M \\
  -smp 2 \\
  -nographic \\
  -kernel "${IFS_OUT}"
"""


def generate_qemu_harness(out_dir: Path, arch: str = "x86_64") -> Path:
    out_dir.mkdir(parents=True, exist_ok=True)
    if arch == "aarch64":
        target = out_dir / "run_qnx8_qemu_aarch64.sh"
        target.write_text(QEMU_AARCH64_SH, encoding="utf-8")
    else:
        target = out_dir / "run_qnx8_qemu_x86_64.sh"
        target.write_text(QEMU_X86_64_SH, encoding="utf-8")
    return target
